		factory: "bufferCount",
		opts: { completeWhenDepsComplete: false, terminalAsRealInput: true },
		body: (ctx) => {
			const b = depBatch(ctx, 0);
			const buf = ctx.state.get<S[]>() ?? [];
			if (b) {
