function mapFromFunction<S, T>(
	fn: (v: S) => T,
	restore?: {
		ref: string;
		config?: GraphCheckpointJson;
		configVersion?: GraphCheckpointJson;
	},
): Operator<S, T> {
	return {
		factory: "map",
		...(restore ? { restore } : {}),
		body: (ctx) => {
			const b = depBatch(ctx, 0);
			if (!b) return;
			for (const v of b) ctx.down([["DATA", fn(v as S)]]);
