			opts.requiredEvidenceKinds.every((kind) =>
				[...state.evidence.values(), ...state.coverageGaps.values()].some(
					(entry) =>
						sameRef(entry.occurrence, occurrence) &&
						entry.evidenceKind === kind &&
						terminalCoverage.has(entry.coverage),
				),
			),
		);
