	type NodeAcquisition,
	runtimeReleaseFailures,
} from "../node/owned-acquisition.js";
import type { NodeVersioningPolicy } from "../node/versioning.js";
import { errorPayload, messageTier, SENTINEL } from "../protocol/messages.js";
import {
