				"void node;",
			],
		],
	],
	["retired-name-preflight", [[scope, "registrar.assertAvailableName(name);", "void name;"]]],
	["construction-during-wave", [[scope, "if (isWaveActive() || currentBatch())", "if (false)"]]],
