	const found = calls.filter((call) => {
		const name = call.expression.getText(sourceFile);
		return (
			(name === "graph.node" || name === "graph.initNode") &&
			optionsName(call).includes(`name: \u0060\u0024{opts.name}/${suffix}\u0060`)
		);
